              "sampleValue": true
            }
          }
        }
      }
    },
    "data": {
      "calendar": {
        "items": {
          "type": "array",
          "description": "日历行程查询结果",
          "sampleValue": [
            {
              "entityId": "calendar-weekend-001",
              "title": "周末学习计划",
              "dtStart": "09:00",
              "dtEnd": "10:00"
            }
          ],
          "items": {
            "type": "object",
            "description": "日程项",
            "properties": {
              "entityId": {
                "type": "string",
                "description": "日程唯一标识符",
                "sampleValue": "calendar-weekend-001"
              },
              "title": {
                "type": "string",
                "description": "日程标题",
                "sampleValue": "周末学习计划"
              },
              "dtStart": {
                "type": "string",
                "description": "日程开始时间",
                "sampleValue": "09:00"
              },
              "dtEnd": {
                "type": "string",
                "description": "日程结束时间",
                "sampleValue": "10:00"
              }
            }
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷计时图标，适合表达应用时长、学习管控和超时限制状态。"
    }
  ]
}

